\operatorname{ClkSub}_{\mathsf G}:
(\mathsf{Ty}_{\mathsf G}\cup\mathsf{Tm}_{\mathsf G})\times\mathsf{ClockVar}_{\mathsf G}\times\mathsf{ClockVar}_{\mathsf G}
\to
\mathsf{Ty}_{\mathsf G}\cup\mathsf{Tm}_{\mathsf G}

\mathsf{ClockCtx}_{\mathsf G}
=
\{\Delta:\Delta\text{ 是 }\mathsf{ClockVar}_{\mathsf G}\text{ 中变量互异的有限序列}\}.

\begin{aligned}
\mathsf{Rule}_{Base}^{G}
= {}&\{(\langle\rangle,\Gamma\vdash b\ \mathsf{type}):b\in\mathsf{Base}_{\mathsf G}\}\\
&\cup\{(\langle\rangle,\Gamma\vdash1\ \mathsf{type}),(\langle\rangle,\Gamma\vdash\mathbb N\ \mathsf{type})\}\\
&\cup\{(\langle\rangle,\Gamma\vdash\star:1),(\langle\rangle,\Gamma\vdash0:\mathbb N)\}\\
&\cup\{(\langle\Gamma\vdash n:\mathbb N\rangle,\Gamma\vdash S(n):\mathbb N)\}.
\end{aligned}

\mathsf{Rule}_{Pi}^{G}
=\{(\langle\Gamma\vdash A\ \mathsf{type},\Gamma,x:A\vdash B\ \mathsf{type}\rangle,
\Gamma\vdash\Pi x:A.B\ \mathsf{type})\}
\cup
\{(\langle\Gamma,x:A\vdash t:B\rangle,\Gamma\vdash\lambda x.t:\Pi x:A.B)\}
\cup
\{(\langle\Gamma\vdash f:\Pi x:A.B,\Gamma\vdash a:A\rangle,\Gamma\vdash f\,a:B[x:=a])\},

\mathsf{Rule}_{Sigma}^{G}
=\{(\langle\Gamma\vdash A\ \mathsf{type},\Gamma,x:A\vdash B\ \mathsf{type}\rangle,
\Gamma\vdash\Sigma x:A.B\ \mathsf{type})\}
\cup
\{(\langle\Gamma\vdash a:A,\Gamma\vdash b:B[x:=a]\rangle,
\Gamma\vdash\langle a,b\rangle:\Sigma x:A.B)\}
\cup
\{(\langle\Gamma\vdash p:\Sigma x:A.B\rangle,\Gamma\vdash\pi_1(p):A)\}
\cup
\{(\langle\Gamma\vdash p:\Sigma x:A.B\rangle,\Gamma\vdash\pi_2(p):B[x:=\pi_1(p)])\},

\mathsf{ProofNode}_{\mathsf G}
=\{(r,\bar J,J,\xi):(\bar J,J)\in\mathsf{Rule}_{\mathsf G},\
r\text{ 为该精确实例tag},\ \xi\text{ 为下列全部参数及所需载荷}\}.
